/* ============================================================
   أطياب الجاسم (React) — صفحات الخط المعلوماتي (InfoPage)

   صفحة عامة تُبنى بالكامل من ملف البيانات (ATYAB_INFO_PAGES) حسب
   المفتاح القادم من المسار (#about · #legal — أمّا #shipping
   و#payments فلهما صفحتان مخصّصتان): الرأس + روابط بقية الصفحات +
   الأقسام بكل أنواعها (note · prose · chips · facts · steps · carriers
   · payments · credentials · policies) + الملاحظة المشتركة أسفلها.

   ★ لا نصّ مكتوب في هذا الملف: كل شيء من البيانات، والصفحة الجديدة
     تُضاف بإضافتها هناك فقط.
   ============================================================ */

import { Link } from "react-router-dom";
import { pathForPage } from "../routes.js";
import { usePageMeta } from "../usePageMeta.js";
import { ATYAB_INFO_PAGES, ATYAB_INFO_NOTE, ATYAB_PAGES } from "../data/appConfig.js";
import { T, t } from "../i18n.js";
import { useAppSelector } from "../redux/hooks.js";
import { Flag, Icon } from "../components/Source/Icons.jsx";
import PaymentMethod from "../components/Source/PaymentMethod.jsx";

const ORDER = ["about", "shipping", "payments", "legal"];

/* عناوين روابط «بقية الصفحات» بالعربية — نفس تسميات النسخة القديمة
   (src/i18n.js: inf.about · inf.shipping · inf.payments · inf.legal).
   اللغة الإنجليزية تأتي من القاموس، وهذه احتياط العربية. */
const PILL_AR = {
  about: "من نحن",
  shipping: "معلومات شركات الشحن",
  payments: "طرق الدفع المتاحة",
  legal: "الامتثال القانوني"
};

/* ★ R7: خريطة احتياطية عربي ← صفحة — تُستعمل فقط عندما يغيب `to`
   عن بيان العنصر (نسخ بيانات أقدم). المطابقة بالاحتواء لا بالمساواة
   حتى تنجو من اختلافات التشكيل والهمزات. */
function labelToPage(label) {
  const ar = String((label && (label.ar || label)) || "");
  if (!ar) return "";
  if (/عطور|العطر/.test(ar)) return "perfumes";
  if (/توزيع|هدايا|هدية|عروض|عرض|خصم|باقة/.test(ar)) return "offers";
  if (/بخور|مبخر|مسك|معمّر|مبخرة/.test(ar)) return "incense";
  if (/عود|معمول|دخون/.test(ar)) return "ouds";
  return "";
}

function Paragraphs(props) {  const paras = String(T(props.text, props.language) || "")
    .split(/\n\s*\n/)
    .filter(function (p) {
      return p.trim();
    });
  return (
    <>
      {paras.map(function (p, i) {
        return (
          <p className="inf-text" key={i}>
            {p.trim()}
          </p>
        );
      })}
    </>
  );
}

function NoteSection(props) {
  const sec = props.sec;
  const language = props.language;
  return (
    <section className={"inf-card inf-card--note inf-tone-" + (sec.tone || "info")}>
      <div className="inf-card-head">
        <Icon name={sec.tone === "draft" ? "spark" : "shield"} className="inf-ico inf-ico--gold" strokeWidth={1.7} />
        <h2>{T(sec.title, language)}</h2>
      </div>
      {sec.text ? <p className="inf-text">{T(sec.text, language)}</p> : null}
      {sec.chips && sec.chips.length ? (
        <ul className="inf-chips">
          {sec.chips.map(function (chip, i) {
            return <li key={i}>{T(chip, language)}</li>;
          })}
        </ul>
      ) : null}
    </section>
  );
}

function Section(props) {
  const sec = props.sec;
  const language = props.language;
  const title = sec.title ? <h2 className="inf-h2">{T(sec.title, language)}</h2> : null;

  switch (sec.kind) {
    case "note":
      return <NoteSection sec={sec} language={language} />;

    case "prose":
      return (
        <section className="inf-card">
          {sec.title ? (
            <div className="inf-card-head">
              <Icon name="leaf" className="inf-ico inf-ico--gold" strokeWidth={1.7} />
              <h2>{T(sec.title, language)}</h2>
            </div>
          ) : null}
          <Paragraphs text={sec.text} language={language} />
        </section>
      );

    case "chips":
      return (
        <section className="inf-card">
          {sec.title ? (
            <div className="inf-card-head">
              <Icon name="check" className="inf-ico inf-ico--gold" strokeWidth={1.8} />
              <h2>{T(sec.title, language)}</h2>
            </div>
          ) : null}
          <ul className="inf-values">
            {(sec.items || []).map(function (item, i) {
              var inner = (
                <>
                  <span className="inf-value-ico">
                    <Icon name={item.icon || "check"} strokeWidth={1.7} />
                  </span>
                  <span>{T(item.label, language)}</span>
                </>
              );
              /* ★ R7: وجهة احتياطية من النص نفسه — حتى لو نسخة البيانات
                 المحلية أقدم وبلا حقل `to`، يبقى الزر ناقلًا لا كلامًا */
              var dest = (item && item.to) || labelToPage(item && item.label);
              return (
                <li key={i}>
                  {dest ? (
                    <Link className="inf-value-link" to={pathForPage(dest, ATYAB_PAGES)}>
                      {inner}
                    </Link>
                  ) : inner}
                </li>
              );
            })}
          </ul>
        </section>
      );

    case "facts":
      return (
        <section className="inf-block">
          {title}
          <ul className="inf-facts">
            {(sec.items || []).map(function (item, i) {
              return (
                <li key={i}>
                  <Icon name={item.icon} className="inf-ico inf-ico--gold" strokeWidth={1.7} />
                  <span className="inf-fact-label">{T(item.label, language)}</span>
                  <b className="inf-fact-value" dir="auto">{T(item.value, language)}</b>
                </li>
              );
            })}
          </ul>
        </section>
      );

    case "steps":
      return (
        <section className="inf-block">
          {title}
          <ol className="inf-steps">
            {(sec.items || []).map(function (item, i) {
              return (
                <li key={i}>
                  {item && item.to ? (
                    <Link to={pathForPage(item.to, ATYAB_PAGES)}>
                      <span>{T(item, language)}</span>
                    </Link>
                  ) : (
                    <span>{T(item, language)}</span>
                  )}
                </li>
              );
            })}
          </ol>
        </section>
      );

    case "carriers":
      return (
        <section className="inf-block">
          {title}
          <div className="inf-countries">
            {(sec.items || []).map(function (country, i) {
              return (
                <article className="inf-country" key={i}>
                  <header className="inf-country-head">
                    <span className="inf-country-flag">
                      <Flag code={country.flag} />
                    </span>
                    <h3>{T(country.country, language)}</h3>
                  </header>
                  {country.note ? <p className="inf-country-note">{T(country.note, language)}</p> : null}
                  <ul className="inf-carriers">
                    {(country.companies || []).map(function (co, j) {
                      return (
                        <li className="inf-carrier" key={j}>
                          <div className="inf-carrier-top">
                            <h4>{language === "en" && co.en ? co.en : co.name}</h4>
                            {co.tag ? <span className="inf-tag">{T(co.tag, language)}</span> : null}
                          </div>
                          <dl className="inf-carrier-meta">
                            <div>
                              <dt>{t(language, "inf.days", "المدة")}</dt>
                              <dd>{T(co.days, language)}</dd>
                            </div>
                            <div>
                              <dt>{t(language, "inf.coverage", "التغطية")}</dt>
                              <dd>{T(co.coverage, language)}</dd>
                            </div>
                          </dl>
                          {co.desc ? <p>{T(co.desc, language)}</p> : null}
                          {co.site ? (
                            <span className="inf-site" dir="ltr">
                              {co.site}
                            </span>
                          ) : null}
                        </li>
                      );
                    })}
                  </ul>
                </article>
              );
            })}
          </div>
        </section>
      );

    case "payments":
      return (
        <section className="inf-block">
          {title}
          <ul className="inf-payments">
            {(sec.items || []).map(function (method, i) {
              return <PaymentMethod method={method} key={i} />;
            })}
          </ul>
        </section>
      );

    case "credentials":
      return (
        <section className="inf-block">
          {title}
          <ul className="inf-creds">
            {(sec.items || []).map(function (cred, i) {
              return (
                <li key={i}>
                  <span className="inf-cred-label">{T(cred.label, language)}</span>
                  <b className="inf-cred-value">{T(cred.value, language)}</b>
                  {cred.note ? <span className="inf-cred-note">{T(cred.note, language)}</span> : null}
                </li>
              );
            })}
          </ul>
        </section>
      );

    case "policies":
      return (
        <section className="inf-block">
          {title}
          <div className="inf-policies">
            {(sec.items || []).map(function (policy, i) {
              return (
                <details className="inf-policy" open={i === 0} key={i}>
                  <summary>
                    <Icon name="doc" className="inf-ico" strokeWidth={1.7} />
                    <span>{T(policy.title, language)}</span>
                    <Icon name="chev" className="inf-chev" strokeWidth={2} />
                  </summary>
                  <p>{T(policy.note, language)}</p>
                  {policy.body ? (
                    <div className="inf-policy-body">
                      <Paragraphs text={policy.body} language={language} />
                    </div>
                  ) : null}
                </details>
              );
            })}
          </div>
        </section>
      );

    default:
      return null;
  }
}

export default function InfoPage(props) {
  const language = useAppSelector(function (s) {
    return s.ui.language;
  });
  const key = props.pageKey || "about";
  const page = (ATYAB_INFO_PAGES || {})[key] || (ATYAB_INFO_PAGES || {}).about;

  usePageMeta({
    route: "info",
    titleAr: page ? T(page.title, "ar") : "",
    titleEn: page ? T(page.title, "en") : ""
  });

  if (!page) return null;

  return (
    <section className="container view inf" id="infoView">
      <header className="inf-hero">
        <span className="inf-eyebrow">{T(page.eyebrow, language)}</span>
        <h1 className="inf-h1">
          {T(page.title, language)} <span className="gold-text">{T(page.titleGold, language)}</span>
        </h1>
        {page.lead ? <p className="inf-lead">{T(page.lead, language)}</p> : null}
      </header>

      <nav className="inf-jump" aria-label={t(language, "inf.otherPages", "صفحات المتجر")}>
        <span className="inf-jump-label">{t(language, "inf.otherPages", "صفحات المتجر")}</span>
        {ORDER.filter(function (k) {
          return k !== key;
        }).map(function (k) {
          return (
            <Link className="inf-pill" to={pathForPage(k, ATYAB_PAGES)} key={k}>
              {t(language, "inf." + k, PILL_AR[k] || k)}
            </Link>
          );
        })}
      </nav>

      <div className="inf-body">
        {(page.sections || []).map(function (sec, i) {
          return <Section sec={sec} language={language} key={i} />;
        })}
      </div>

      {ATYAB_INFO_NOTE ? (
        <p className="inf-foot-note">
          <Icon name="spark" className="inf-ico" strokeWidth={1.6} />
          <span>{T(ATYAB_INFO_NOTE, language)}</span>
        </p>
      ) : null}
    </section>
  );
}
