/* ============================================================
   أطياب الجاسم (React) — بيانات الصفحة (usePageMeta)

   كل صفحة صارت هي المسؤولة عن نفسها: تُنادي هذا الخطّاف في أوّلها
   فتُعلن اسمها (data-route) وكتالوجها (data-catalog) وعنوان تبويب
   المتصفّح — بدل أن يعرف App كم صفحة وكيف تسمّى كل واحدة.

   ★ الخطّاف يقرأ اللغة من Redux بنفسه، فعنوان التبويب يتبدّل فوراً
     عند تغيير اللغة بلا أي كود إضافي في الصفحة.
   ------------------------------------------------------------
     usePageMeta({ route: "offers", catalog: "", titleAr: "العروض", titleEn: "Offers" })
   ★ `active: false` تعني أنّ الصفحة مُركَّبة لكنها مخفيّة (الرئيسية تبقى
     مُركَّبة دائماً داخل .route-slot) — فلا تكتب عنوانها ولا data-route
     وهي مخفيّة، وتُعيد كتابتهما بمجرد أن تعود نشطة.
   ============================================================ */

import { useEffect, useMemo } from "react";
import { useAppSelector } from "./redux/hooks.js";

const BASE_TITLE_AR = "أطياب الجاسم — العطور والبخور";
const BASE_TITLE_EN = "Atyab Al-Jasem — Perfumes & Bakhoor";

/* عنوان التبويب: «اسم الصفحة — اسم المتجر» (وبدونه للصفحة الرئيسية) */
export function pageTitle(title, language) {
  const base = language === "en" ? BASE_TITLE_EN : BASE_TITLE_AR;
  return title ? title + " — " + base : base;
}

export function usePageMeta(meta) {
  const language = useAppSelector(function (s) {
    return s.ui.language;
  });
  const routeKey = (meta && meta.route) || "";
  const catalogKey = (meta && meta.catalog) || "";
  const titleAr = meta && meta.titleAr;
  const titleEn = meta && meta.titleEn;
  const active = !meta || meta.active !== false;

  const title = useMemo(
    function () {
      return pageTitle(language === "en" ? titleEn : titleAr, language);
    },
    [language, titleAr, titleEn],
  );

  useEffect(
    function () {
      if (!active) return;
      document.title = title;
    },
    [title, active],
  );

  useEffect(
    function () {
      if (!active) return;
      const root = document.documentElement;
      root.setAttribute("data-route", routeKey);
      root.setAttribute("data-catalog", catalogKey);
    },
    [routeKey, catalogKey, active],
  );

  return title;
}
