/* ============================================================
   أطياب الجاسم (React) — بطاقة طريقة الدفع (PaymentMethod)

   بطاقة واحدة تعرض معلومات طريقة دفع: الشعار، الاسم، نوعها، الوصف،
   وأين تتوفّر. طريقة الدفع تأتي من ATYAB_PAYMENTS في ملف البيانات.
   ★ PaymentMethodPage يستدعيها لكل طريقة حتى تنتهي القائمة.
   ============================================================ */

import { T } from "../../i18n.js";
import { useAppSelector } from "../../redux/hooks.js";
import { Icon, PayMark } from "./Icons.jsx";

/* الدفع عند الاستلام هو الوحيد الفعّال — البقية "قريبًا" */
function isCodMethod(m) {
  if (!m) return false;
  if (String(m.key || "").toLowerCase() === "cod") return true;
  var s = [m.name, m.en, m.title].filter(Boolean).join(" ");
  return /استلام|cash|نقد/i.test(s);
}

export default function PaymentMethod(props) {
  const method = props.method;
  const language = useAppSelector(function (s) {
    return s.ui.language;
  });
  const isEn = language === "en";
  if (!method) return null;

  var cod = isCodMethod(method);
  return (
    <li className={"inf-pay pm-mark--" + (method.tone || "plain") + (cod ? "" : " is-soon")}>
      {cod ? null : <span className="pm-soon">{isEn ? "Soon" : "قريبًا"}</span>}
      <span className="pm-mark">
        <PayMark mark={method.mark} />
      </span>
      <div className="pm-body">
        <div className="pm-head">
          <h3>{isEn && method.en ? method.en : method.name}</h3>
          {method.kind ? <span className="inf-tag">{T(method.kind, language)}</span> : null}
        </div>
        {method.desc ? <p>{T(method.desc, language)}</p> : null}
        {method.where ? (
          <span className="pm-where">
            <Icon name="globe" className="pm-where-ico" strokeWidth={1.7} />
            {T(method.where, language)}
          </span>
        ) : null}
      </div>
    </li>
  );
}
